    <script>
        /* ===========================================
           SLIDE PRESENTATION CONTROLLER
           =========================================== */
        class SlidePresentation {
            constructor() {
                this.slides = document.querySelectorAll('.slide');
                this.currentSlide = 0;
                this.progressBar = document.getElementById('progressBar');

                this.setupIntersectionObserver();
                this.setupKeyboardNav();
                this.setupScrollNav();
                this.updateProgressBar();
            }

            setupIntersectionObserver() {
                const observer = new IntersectionObserver((entries) => {
                    entries.forEach(entry => {
                        if (entry.isIntersecting) {
                            entry.target.classList.add('visible');
                            // Update current slide index based on what's visible
                            const index = Array.from(this.slides).indexOf(entry.target);
                            if (index !== -1) {
                                this.currentSlide = index;
                                this.updateProgressBar();
                            }
                        }
                    });
                }, { threshold: 0.5 });

                this.slides.forEach(slide => observer.observe(slide));
            }

            setupKeyboardNav() {
                window.addEventListener('keydown', (e) => {
                    if (e.key === 'ArrowDown' || e.key === 'ArrowRight' || e.key === 'PageDown' || e.key === ' ') {
                        e.preventDefault();
                        this.goToSlide(this.currentSlide + 1);
                    } else if (e.key === 'ArrowUp' || e.key === 'ArrowLeft' || e.key === 'PageUp') {
                        e.preventDefault();
                        this.goToSlide(this.currentSlide - 1);
                    }
                });
            }

            setupScrollNav() {
                let isScrolling = false;
                window.addEventListener('wheel', (e) => {
                    if (isScrolling) return;

                    if (e.deltaY > 50) {
                        isScrolling = true;
                        this.goToSlide(this.currentSlide + 1);
                        setTimeout(() => isScrolling = false, 800);
                    } else if (e.deltaY < -50) {
                        isScrolling = true;
                        this.goToSlide(this.currentSlide - 1);
                        setTimeout(() => isScrolling = false, 800);
                    }
                }, { passive: true });
            }

            goToSlide(index) {
                if (index >= 0 && index < this.slides.length) {
                    this.slides[index].scrollIntoView({ behavior: 'smooth' });
                    this.currentSlide = index;
                    this.updateProgressBar();
                }
            }

            updateProgressBar() {
                if (!this.progressBar) return;
                const progress = (this.currentSlide / (this.slides.length - 1)) * 100;
                this.progressBar.style.width = `${progress}%`;
            }
        }

        document.addEventListener('DOMContentLoaded', () => {
            new SlidePresentation();
            // Trigger visible on first slide immediately
            if (document.querySelector('.slide')) {
                document.querySelector('.slide').classList.add('visible');
            }
        });
    </script>
